    cards: [
      { title: 'Không được làm', emoji: '🚫', body: 'Đốt pháo nổ; nghịch lửa, diêm; chạm, cưa, đập vật lạ nghi bom mìn; chơi đùa nơi chứa hóa chất; tự ý dùng bếp gas khi chưa biết cách.', example: 'Thấy vật lạ hình quả đạn ngoài đồng: không chạm, đánh dấu, báo người lớn, công an.' },
      { title: 'Khi có cháy', emoji: '🔥', body: 'Hô hoán → gọi 114 → thoát theo lối thoát hiểm → cúi thấp, che mũi miệng bằng khăn ướt → không dùng thang máy → không quay lại.', example: 'Khói độc nguy hiểm hơn lửa; khí nóng và khói bốc lên cao.' },
      { title: 'Chất độc hại', emoji: '☠️', body: 'Cất thuốc trừ sâu, hóa chất tẩy rửa xa thức ăn và tầm tay trẻ nhỏ; đọc nhãn; đeo găng, khẩu trang khi dùng.', example: 'Liên hệ KHTN bài 1: kí hiệu cảnh báo hóa chất.' },
    ],
    traps: ['Nghĩ đốt pháo dịp Tết là được phép.', 'Đi thang máy khi có cháy.', 'Tò mò mang vật lạ về nhà.'],
